def comps2(g,bg):
    R=len(g);C=len(g[0]);seen=set();out=[]
    for i in range(R):
        for j in range(C):
            if (i,j) in seen or g[i][j]==bg: continue
            st=[(i,j)];cell=[]
            while st:
                y,x=st.pop()
                if (y,x) in seen: continue
                seen.add((y,x));cell.append((y,x))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<R and 0<=nx<C and (ny,nx) not in seen and g[ny][nx]!=bg: st.append((ny,nx))
            out.append(cell)
    return out
